import * as T from 'three';
export class RoadEffects{
 constructor(scene){this.count=96;this.cursor=0;this.position=new Float32Array(this.count*3);this.life=new Float32Array(this.count);this.velocity=new Float32Array(this.count*3);this.color=new Float32Array(this.count*3);const g=new T.BufferGeometry();g.setAttribute('position',new T.BufferAttribute(this.position,3));g.setAttribute('life',new T.BufferAttribute(this.life,1));g.setAttribute('color',new T.BufferAttribute(this.color,3));this.geometry=g;const mat=new T.ShaderMaterial({transparent:true,depthWrite:false,vertexColors:true,uniforms:{},vertexShader:'attribute float life; varying float alpha; varying vec3 tint; void main(){alpha=life*.24; tint=color;vec4 p=modelViewMatrix*vec4(position,1.);gl_Position=projectionMatrix*p;gl_PointSize=clamp((1.-life)*90.+25.,12.,100.)/max(1.,-p.z*.15);}',fragmentShader:'varying float alpha;varying vec3 tint;void main(){float d=length(gl_PointCoord-.5)*2.;gl_FragColor=vec4(tint,alpha*smoothstep(1.,.1,d));}'});const points=new T.Points(g,mat);points.frustumCulled=false;scene.add(points)}
 update(dt,p){for(let i=0;i<this.count;i++){if(this.life[i]<=0)continue;this.life[i]=Math.max(0,this.life[i]-dt*.6);this.position[i*3]+=this.velocity[i*3]*dt;this.position[i*3+1]+=dt*.28;this.position[i*3+2]+=this.velocity[i*3+2]*dt}if((p.slip>.15||p.surface!=='asphalt')&&p.speed>5&&!p.crashed){const i=this.cursor++%this.count;this.life[i]=1;this.position.set([p.x-Math.sin(p.heading)*.7,p.y+.14,p.z+Math.cos(p.heading)*.7],i*3);this.velocity.set([(Math.random()-.5)*.6,0,(Math.random()-.5)*.6],i*3);this.color.set(p.surface==='asphalt'?[.65,.67,.67]:[.46,.39,.27],i*3)}for(const a of Object.values(this.geometry.attributes))a.needsUpdate=true}
}
